(()=>{ const starts = {pim_room:[5,8],hallway:[3,3],downstairs:[20,3],yard:[10,4],attic_real:[6,6],mom_room:[6,6],fort:[12,9],crumb_1:[1,10],crumb_town:[1,10],crumb_river:[12,20],crumb_peak:[9,17],carpet_1:[30,11],carpet_village:[12,16],static_woods:[28,11],static_heart:[9,13],attic_1:[3,12],attic_2:[9,11],attic_3:[2,5],attic_4:[7,8],keep_1:[10,22],keep_2:[13,16],keep_3:[9,13],yard_after:[10,8]};
 State.newGame(); const flagsOn = ['fort_intro_done','momo_joined','ladle_moved','channels_solved','attic_door1','photo_done','keep_open','momo_reveal','want_album','ladder_down'];
 for (const f of flagsOn) State.d.flags[f]=true; State.d.chapter = 4;
 const out = {};
 for (const id of Object.keys(starts)) { try { const [sx,sy]=starts[id]; const s = new MapScene(id, sx, sy, 'down'); s.load(); const W=s.w,H=s.h; const seen=new Set([sx+','+sy]); const q=[[sx,sy]]; const ok=(x,y)=> s.inBounds(x,y) && !s.block[y][x] && !s.events.some(e=>e.solid && e.visible!==false && (e.w? (x>=e.x&&x<e.x+e.w&&y>=e.y&&y<e.y+(e.h||1)) : (e.x===x&&e.y===y)) && !e.pushable);
 while(q.length){const [x,y]=q.shift(); for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=nx+','+ny; if(!seen.has(k)&&ok(nx,ny)){seen.add(k);q.push([nx,ny]);}}}
 const bad=[]; const reach=(x,y)=>seen.has(x+','+y); const near=(x,y,w=1,h=1)=>{for(let yy=y-1;yy<=y+h;yy++)for(let xx=x-1;xx<=x+w;xx++){if(reach(xx,yy))return true;}for(let yy=y;yy<y+h;yy++)for(let xx=x;xx<x+w;xx++){if(reach(xx,yy)||reach(xx,yy+2)||reach(xx,yy-2)||reach(xx-2,yy)||reach(xx+2,yy))return true;} return false;};
 for (const e of s.events) { if (e.trigger==='none' || e.dynamic) continue; if(!near(e.x,e.y,e.w||1,e.h||1)) bad.push('event '+e.id+'@'+e.x+','+e.y); }
 for (const ex of s.def.exits||[]) { if (ex.cond && !ex.cond()) continue; let any=false; for(let yy=ex.y;yy<ex.y+(ex.h||1);yy++)for(let xx=ex.x;xx<ex.x+(ex.w||1);xx++) if(reach(xx,yy)) any=true; if(!any) bad.push('exit to '+ex.to+'@'+ex.x+','+ex.y); }
 for (const en of s.enemies) { if(!reach(en.x,en.y)) bad.push('enemy '+en.troop+'@'+en.x+','+en.y); }
 if (bad.length) out[id]=bad; } catch(err) { out[id] = 'ERR '+err.message; } }
 return out; })()
